CREATE TABLE `ledger_lines` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `farm_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entry_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `account_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `debit` decimal(16,2) NOT NULL DEFAULT '0.00',
  `credit` decimal(16,2) NOT NULL DEFAULT '0.00',
  `cost_center_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cost_center_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `memo` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ledger_lines_farm_id_account_id_index` (`farm_id`,`account_id`),
  KEY `ledger_lines_farm_id_entry_id_index` (`farm_id`,`entry_id`),
  KEY `ledger_lines_farm_id_cost_center_type_cost_center_id_index` (`farm_id`,`cost_center_type`,`cost_center_id`),
  CONSTRAINT `ledger_lines_farm_id_account_id_foreign` FOREIGN KEY (`farm_id`, `account_id`) REFERENCES `ledger_accounts` (`farm_id`, `id`),
  CONSTRAINT `ledger_lines_farm_id_entry_id_foreign` FOREIGN KEY (`farm_id`, `entry_id`) REFERENCES `ledger_entries` (`farm_id`, `id`),
  CONSTRAINT `ledger_lines_farm_id_foreign` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`),
  CONSTRAINT `ledger_lines_amount_check` CHECK (((`debit` >= 0) and (`credit` >= 0) and (((`debit` > 0) and (`credit` = 0)) or ((`credit` > 0) and (`debit` = 0)))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `ledger_lines` WRITE;
