  UNIQUE KEY `payroll_runs_farm_id_code_unique` (`farm_id`,`code`),
  KEY `payroll_runs_prepared_by_foreign` (`prepared_by`),
  KEY `payroll_runs_approved_by_foreign` (`approved_by`),
  KEY `payroll_runs_entry_fk` (`farm_id`,`ledger_entry_id`),
  CONSTRAINT `payroll_runs_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `payroll_runs_entry_fk` FOREIGN KEY (`farm_id`, `ledger_entry_id`) REFERENCES `ledger_entries` (`farm_id`, `id`),
  CONSTRAINT `payroll_runs_farm_id_foreign` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`),
  CONSTRAINT `payroll_runs_prepared_by_foreign` FOREIGN KEY (`prepared_by`) REFERENCES `users` (`id`),
  CONSTRAINT `payroll_runs_period_check` CHECK (((`period_end` >= `period_start`) and (`paid_amount` >= 0) and (`paid_amount` <= `total_net`))),
  CONSTRAINT `payroll_runs_status_check` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'approved',_utf8mb4'paid',_utf8mb4'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
