DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `farm_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `list_price` decimal(16,2) NOT NULL,
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `min_order_quantity` decimal(14,3) DEFAULT NULL,
  `availability_note` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inventory_item_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `income_account_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `media_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_published` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_farm_id_id_unique` (`farm_id`,`id`),
  UNIQUE KEY `products_farm_id_code_unique` (`farm_id`,`code`),
  KEY `products_created_by_foreign` (`created_by`),
  KEY `products_item_fk` (`farm_id`,`inventory_item_id`),
  KEY `products_account_fk` (`farm_id`,`income_account_id`),
  KEY `products_media_fk` (`farm_id`,`media_id`),
  KEY `products_farm_id_is_published_is_active_index` (`farm_id`,`is_published`,`is_active`),
  CONSTRAINT `products_account_fk` FOREIGN KEY (`farm_id`, `income_account_id`) REFERENCES `ledger_accounts` (`farm_id`, `id`),
  CONSTRAINT `products_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `products_farm_id_foreign` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`),
  CONSTRAINT `products_item_fk` FOREIGN KEY (`farm_id`, `inventory_item_id`) REFERENCES `inventory_items` (`farm_id`, `id`),
  CONSTRAINT `products_media_fk` FOREIGN KEY (`farm_id`, `media_id`) REFERENCES `media` (`farm_id`, `id`),
  CONSTRAINT `products_price_check` CHECK (((`list_price` >= 0) and ((`min_order_quantity` is null) or (`min_order_quantity` > 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
