  UNIQUE KEY `purchase_order_lines_farm_id_id_unique` (`farm_id`,`id`),
  KEY `purchase_order_lines_farm_id_order_id_foreign` (`farm_id`,`order_id`),
  KEY `purchase_order_lines_farm_id_item_id_foreign` (`farm_id`,`item_id`),
