CREATE TABLE `shipments` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `farm_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'dispatched',
  `customer_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_invoice_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trace_batch_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `destination` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vehicle` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driver` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dispatched_at` datetime NOT NULL,
  `dispatched_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `received_by` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `failure_reason` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `closed_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `sales_order_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shipments_farm_id_id_unique` (`farm_id`,`id`),
  UNIQUE KEY `shipments_farm_id_code_unique` (`farm_id`,`code`),
  KEY `shipments_dispatched_by_foreign` (`dispatched_by`),
  KEY `shipments_closed_by_foreign` (`closed_by`),
  KEY `shipments_farm_id_status_dispatched_at_index` (`farm_id`,`status`,`dispatched_at`),
  KEY `shipments_customer_fk` (`farm_id`,`customer_id`),
  KEY `shipments_invoice_fk` (`farm_id`,`customer_invoice_id`),
  KEY `shipments_batch_fk` (`farm_id`,`trace_batch_id`),
  KEY `shipments_farm_id_sales_order_id_index` (`farm_id`,`sales_order_id`),
  CONSTRAINT `shipments_batch_fk` FOREIGN KEY (`farm_id`, `trace_batch_id`) REFERENCES `trace_batches` (`farm_id`, `id`),
  CONSTRAINT `shipments_closed_by_foreign` FOREIGN KEY (`closed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `shipments_customer_fk` FOREIGN KEY (`farm_id`, `customer_id`) REFERENCES `customers` (`farm_id`, `id`),
  CONSTRAINT `shipments_dispatched_by_foreign` FOREIGN KEY (`dispatched_by`) REFERENCES `users` (`id`),
  CONSTRAINT `shipments_farm_id_foreign` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`),
  CONSTRAINT `shipments_invoice_fk` FOREIGN KEY (`farm_id`, `customer_invoice_id`) REFERENCES `customer_invoices` (`farm_id`, `id`),
  CONSTRAINT `shipments_order_fk` FOREIGN KEY (`farm_id`, `sales_order_id`) REFERENCES `sales_orders` (`farm_id`, `id`),
  CONSTRAINT `shipments_status_check` CHECK ((`status` in (_utf8mb4'dispatched',_utf8mb4'delivered',_utf8mb4'failed')))
