CREATE TABLE `trace_batches` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `farm_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `batch_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kind` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` decimal(14,3) DEFAULT NULL,
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `product_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `origin_plot_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_type` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `trace_batches_farm_id_id_unique` (`farm_id`,`id`),
  UNIQUE KEY `trace_batches_batch_code_unique` (`batch_code`),
  KEY `trace_batches_created_by_foreign` (`created_by`),
  KEY `trace_batches_farm_id_kind_status_index` (`farm_id`,`kind`,`status`),
  KEY `trace_batches_farm_id_created_at_index` (`farm_id`,`created_at`),
  KEY `trace_batches_farm_id_source_type_source_id_index` (`farm_id`,`source_type`,`source_id`),
  KEY `trace_batches_origin_plot_fk` (`farm_id`,`origin_plot_id`),
  CONSTRAINT `trace_batches_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `trace_batches_farm_id_foreign` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`),
  CONSTRAINT `trace_batches_origin_plot_fk` FOREIGN KEY (`farm_id`, `origin_plot_id`) REFERENCES `farm_plots` (`farm_id`, `id`),
  CONSTRAINT `trace_batches_kind_check` CHECK ((`kind` in (_utf8mb4'seed_lot',_utf8mb4'input_lot',_utf8mb4'nursery',_utf8mb4'crop_lot',_utf8mb4'harvest',_utf8mb4'animal',_utf8mb4'animal_product',_utf8mb4'processed',_utf8mb4'packaged',_utf8mb4'shipment'))),
  CONSTRAINT `trace_batches_quantity_check` CHECK (((`quantity` is null) or (`quantity` >= 0))),
  CONSTRAINT `trace_batches_status_check` CHECK ((`status` in (_utf8mb4'open',_utf8mb4'closed',_utf8mb4'recalled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
