  `occurred_at` datetime(6) NOT NULL,
  `recorded_at` datetime(6) NOT NULL,
  `actor_user_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `worker_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plot_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `gps_accuracy_m` decimal(8,2) DEFAULT NULL,
  `subject_type` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subject_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payload` json NOT NULL,
  `corrects_event_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `farm_seq` bigint unsigned NOT NULL,
  `prev_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `trace_events_farm_id_id_unique` (`farm_id`,`id`),
  UNIQUE KEY `trace_events_farm_id_farm_seq_unique` (`farm_id`,`farm_seq`),
  KEY `trace_events_actor_user_id_foreign` (`actor_user_id`),
  KEY `trace_events_farm_id_batch_id_occurred_at_index` (`farm_id`,`batch_id`,`occurred_at`),
  KEY `trace_events_farm_id_subject_type_subject_id_index` (`farm_id`,`subject_type`,`subject_id`),
  KEY `trace_events_farm_id_recorded_at_index` (`farm_id`,`recorded_at`),
  KEY `trace_events_farm_id_corrects_event_id_foreign` (`farm_id`,`corrects_event_id`),
  KEY `trace_events_plot_fk` (`farm_id`,`plot_id`),
  KEY `trace_events_farm_id_worker_id_index` (`farm_id`,`worker_id`),
  KEY `trace_events_farm_id_event_type_index` (`farm_id`,`event_type`),
  CONSTRAINT `trace_events_actor_user_id_foreign` FOREIGN KEY (`actor_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `trace_events_farm_id_batch_id_foreign` FOREIGN KEY (`farm_id`, `batch_id`) REFERENCES `trace_batches` (`farm_id`, `id`),
  CONSTRAINT `trace_events_farm_id_corrects_event_id_foreign` FOREIGN KEY (`farm_id`, `corrects_event_id`) REFERENCES `trace_events` (`farm_id`, `id`),
  CONSTRAINT `trace_events_farm_id_foreign` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`),
  CONSTRAINT `trace_events_plot_fk` FOREIGN KEY (`farm_id`, `plot_id`) REFERENCES `farm_plots` (`farm_id`, `id`),
  CONSTRAINT `trace_events_worker_fk` FOREIGN KEY (`farm_id`, `worker_id`) REFERENCES `workers` (`farm_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
