/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `worker_leave` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `farm_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `worker_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kind` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_on` date NOT NULL,
  `to_on` date NOT NULL,
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'requested',
  `requested_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decided_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decided_at` timestamp NULL DEFAULT NULL,
  `decision_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `worker_leave_farm_id_id_unique` (`farm_id`,`id`),
  KEY `worker_leave_requested_by_foreign` (`requested_by`),
  KEY `worker_leave_decided_by_foreign` (`decided_by`),
  KEY `worker_leave_farm_id_status_from_on_index` (`farm_id`,`status`,`from_on`),
  KEY `worker_leave_farm_id_worker_id_from_on_index` (`farm_id`,`worker_id`,`from_on`),
  CONSTRAINT `worker_leave_decided_by_foreign` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `worker_leave_farm_id_foreign` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`),
  CONSTRAINT `worker_leave_farm_id_worker_id_foreign` FOREIGN KEY (`farm_id`, `worker_id`) REFERENCES `workers` (`farm_id`, `id`),
  CONSTRAINT `worker_leave_requested_by_foreign` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `worker_leave_dates_check` CHECK ((`to_on` >= `from_on`)),
  CONSTRAINT `worker_leave_kind_check` CHECK ((`kind` in (_utf8mb4'annual',_utf8mb4'sick',_utf8mb4'compassionate',_utf8mb4'unpaid',_utf8mb4'other'))),
  CONSTRAINT `worker_leave_status_check` CHECK ((`status` in (_utf8mb4'requested',_utf8mb4'approved',_utf8mb4'rejected',_utf8mb4'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
