CREATE TABLE `worker_task_logs` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `farm_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `to_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applied` tinyint(1) NOT NULL DEFAULT '1',
  `occurred_at` timestamp(6) NOT NULL,
  `lat` decimal(9,6) DEFAULT NULL,
  `lng` decimal(9,6) DEFAULT NULL,
  `accuracy_m` decimal(8,2) DEFAULT NULL,
  `quantity` decimal(12,3) DEFAULT NULL,
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `device_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recorded_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `worker_task_logs_farm_id_id_unique` (`farm_id`,`id`),
  KEY `worker_task_logs_recorded_by_foreign` (`recorded_by`),
  KEY `worker_task_logs_farm_id_task_id_occurred_at_index` (`farm_id`,`task_id`,`occurred_at`),
  CONSTRAINT `worker_task_logs_farm_id_foreign` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`),
  CONSTRAINT `worker_task_logs_farm_id_task_id_foreign` FOREIGN KEY (`farm_id`, `task_id`) REFERENCES `worker_tasks` (`farm_id`, `id`),
  CONSTRAINT `worker_task_logs_recorded_by_foreign` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`),
  CONSTRAINT `worker_task_logs_event_check` CHECK ((`event` in (_utf8mb4'start',_utf8mb4'pause',_utf8mb4'resume',_utf8mb4'submit',_utf8mb4'verify',_utf8mb4'reject',_utf8mb4'cancel',_utf8mb4'note'))),
  CONSTRAINT `worker_task_logs_point_check` CHECK ((((`lat` is null) = (`lng` is null)) and ((`lat` is null) or ((`lat` between -(90) and 90) and (`lng` between -(180) and 180)))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
